effect.shader:
const float PI = 3.14159265;
void main(){
  vec2 uv = acScreenNorm;
  float ar = acScreenSize.x / max(acScreenSize.y, 1.0);
  vec2 p = (uv - vec2(centerX, centerY)) * vec2(ar, 1.0);
  float r = length(p);
  float a = atan(p.y, p.x) + radians(angle);
  float seg = PI / max(segments, 2.0);
  a = mod(a, seg * 2.0);
  a = abs(a - seg);
  vec2 q = vec2(cos(a), sin(a)) * r;
  uv = q / vec2(ar, 1.0) + vec2(centerX, centerY);
  vec4 k = texture2DCv(inputImg.texture, uv);
  gl_FragColor = mix(texture2DCv(inputImg.texture, acScreenNorm), k, mixAmt);
}
